import{_ as e,b as a,o as t,a8 as i}from"./chunks/framework.BEMRIPir.js";const v=JSON.parse('{"title":"v3 优化内容","description":"","frontmatter":{},"headers":[],"relativePath":"material/endorsement/framework/vue/v3-optimizing-content/index.md","filePath":"material/endorsement/framework/vue/v3-optimizing-content/index.md"}'),o={name:"material/endorsement/framework/vue/v3-optimizing-content/index.md"},l=i('<h1 id="v3-优化内容" tabindex="-1">v3 优化内容 <a class="header-anchor" href="#v3-优化内容" aria-label="Permalink to &quot;v3 优化内容&quot;">​</a></h1><h2 id="响应式-api-的变化" tabindex="-1">响应式 API 的变化 <a class="header-anchor" href="#响应式-api-的变化" aria-label="Permalink to &quot;响应式 API 的变化&quot;">​</a></h2><p>使用 Proxy 代替 Object.defineProperty，结合 Reflect 重构响应式系统，Proxy 可以监听到数组下标的变化和对象新增的属性，整体的代理模式为对象本身，且可拦截 apply、has 等方法</p><div class="info custom-block"><p class="custom-block-title">信息</p><ul><li>在 vue2 中，使用深层属性嵌套的对象做响应式，响应式处理默认是递归的，当数据层级过深时，内存消耗会特别高，因此数据需要尽量扁平化，从而产生了一些特定的处理方案</li><li>在 vue3 中，使用 Proxy 并不能监听到对象内部深层次属性的变化，因为它的处理方式需要在 getter 方法中去做响应式递归，这样做的好处在于，只有在真正访问到内部属性时，才会变为响应式，大大降低了性能消耗</li></ul></div><h2 id="全局-api-变化" tabindex="-1">全局 API 变化 <a class="header-anchor" href="#全局-api-变化" aria-label="Permalink to &quot;全局 API 变化&quot;">​</a></h2><ul><li>vue2 导出全局的 vue 对象，在单元测试中，很容易污染全局环境以及带来冲突</li><li>vue3 通过 createApp 创建 app 实例，一切操作修改直接转变为操作 vue 实例</li></ul><h2 id="代码体积优化" tabindex="-1">代码体积优化 <a class="header-anchor" href="#代码体积优化" aria-label="Permalink to &quot;代码体积优化&quot;">​</a></h2><ul><li>在代码中使用 vue3，需要设置 <code>&lt;script type=&quot;module&quot;&gt;&lt;/script&gt;</code> 使其支持 esm，由于大部分 vue 提供的 api 都可以被 tree-shaking，结合 esm 具有静态结构的特性，使得在代码编译时依赖关系就已确定。</li><li>实现了更好的 tree-shaking，它使得代码按需编译，并且通过将无用的模块进行 &quot;剪枝&quot;，从而让未使用的 api 不参与最终打包，最终缩减代码体积</li><li>通过调整代码结构，将 vue 自身作为一个对象操作，从而使得一些可能不会用到的功能就会被 tree-shaking 掉，最终使代码体积变得更小</li></ul><h2 id="插槽和模版" tabindex="-1">插槽和模版 <a class="header-anchor" href="#插槽和模版" aria-label="Permalink to &quot;插槽和模版&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">插槽</p><p>由于 vue2 的机制，导致作用域插槽会导致父组件重渲染。vue3 通过将作用域插槽转换为函数形式，解决了子组件重渲染时父组件也会重渲染的问题，提升了模版性能</p></div><div class="tip custom-block"><p class="custom-block-title">模版</p><p>在 render 函数方面，vue3 也做了一系列改变，可以直接通过 api 来生成 vdom</p></div>',11),r=[l];function s(n,c,d,u,p,m){return t(),a("div",null,r)}const _=e(o,[["render",s]]);export{v as __pageData,_ as default};
